// =============================================================================
// textures.ts — a tiny, OPT-IN library of embedded bitmap textures for the
// material texture stack's 'bitmap' layer kind (see types.ts's TextureLayer).
//
// Everything else in this engine is pure math — zero external assets, byte-
// identical output from a seed alone. That's deliberate: it's what lets a
// server generate infinite unique sprites with nothing to ship or load. This
// module is the one deliberate exception, and it stays small on purpose:
// each entry is a single tiny (32x32) tileable RGBA source, embedded as raw
// base64 right here in the source file (not a fetched/loaded asset), decoded
// once at import time. No material uses one unless it explicitly asks for a
// 'bitmap' texture layer — every existing material is completely unaffected.
//
// Sources: hand-painted tileable pattern references, cropped to single tiles.
// =============================================================================

/** Minimal base64 -> bytes decoder. No atob()/Buffer dependency, so this
 * works identically in Node and in a browser bundle (see index.ts's IIFE demo). */
function decodeBase64(b64: string): Uint8ClampedArray {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const lookup = new Uint8Array(256);
  for (let i = 0; i < alphabet.length; i++) lookup[alphabet.charCodeAt(i)] = i;

  const clean = b64.replace(/=+$/, '');
  const len = clean.length;
  const bytesLen = (len * 3) >> 2;
  const out = new Uint8ClampedArray(bytesLen);
  let outI = 0;
  for (let i = 0; i < len; i += 4) {
    const a = lookup[clean.charCodeAt(i)];
    const b = lookup[clean.charCodeAt(i + 1)];
    const c = i + 2 < len ? lookup[clean.charCodeAt(i + 2)] : 0;
    const d = i + 3 < len ? lookup[clean.charCodeAt(i + 3)] : 0;
    const triple = (a << 18) | (b << 12) | (c << 6) | d;
    if (outI < bytesLen) out[outI++] = (triple >> 16) & 0xff;
    if (outI < bytesLen) out[outI++] = (triple >> 8) & 0xff;
    if (outI < bytesLen) out[outI++] = triple & 0xff;
  }
  return out;
}

export interface BitmapSource { width: number; height: number; data: Uint8ClampedArray; }

function decodeTile(width: number, height: number, b64: string): BitmapSource {
  return { width, height, data: decodeBase64(b64) };
}

// -- Embedded sources (32x32, RGBA, seamlessly tileable) --------------------

const COBBLESTONE_B64 = '';
const CRATE_WOOD_B64 = '';

/** Lazily-decoded so importing this module doesn't pay the decode cost unless a texture is actually used. */
const LAVA_B64 = '';
const BRICK_B64 = '';

const GRASS_A_B64 = '';
const GRASS_B_B64 = '';
const GRASS_C_B64 = '';

let _cobblestone: BitmapSource | null = null;
let _crateWood: BitmapSource | null = null;
let _lava: BitmapSource | null = null;
let _brick: BitmapSource | null = null;
let _grassA: BitmapSource | null = null;
let _grassB: BitmapSource | null = null;
let _grassC: BitmapSource | null = null;

export const BITMAP_TEXTURES = {
  get cobblestone(): BitmapSource {
    return _cobblestone ?? (_cobblestone = decodeTile(32, 32, COBBLESTONE_B64));
  },
  get crateWood(): BitmapSource {
    return _crateWood ?? (_crateWood = decodeTile(32, 32, CRATE_WOOD_B64));
  },
  get lava(): BitmapSource {
    return _lava ?? (_lava = decodeTile(32, 32, LAVA_B64));
  },
  get brick(): BitmapSource {
    return _brick ?? (_brick = decodeTile(32, 32, BRICK_B64));
  },
  get grassA(): BitmapSource {
    return _grassA ?? (_grassA = decodeTile(48, 48, GRASS_A_B64));
  },
  get grassB(): BitmapSource {
    return _grassB ?? (_grassB = decodeTile(48, 48, GRASS_B_B64));
  },
  get grassC(): BitmapSource {
    return _grassC ?? (_grassC = decodeTile(48, 48, GRASS_C_B64));
  },
};
